    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      margin-top: 0.2rem;
    }

    .button,
    .button-secondary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.8rem 1.2rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
    }

    .button {
      background: var(--brand);
      color: #fff;
      box-shadow: 0 16px 32px rgba(35, 71, 217, 0.22);
    }

    .button-secondary {
      background: transparent;
      color: var(--text);
      border-color: var(--line);
    }

    .button:hover,
    .button-secondary:hover,
    .card-link:hover,
    .button:focus-visible,
    .button-secondary:focus-visible,
    .card-link:focus-visible,
    .icon-button:focus-visible {
      transform: translateY(-1px);
      outline: 3px solid rgba(35, 71, 217, 0.2);
      outline-offset: 2px;
    }

    .hero-metrics {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.9rem;
      margin-top: 0.3rem;
    }

    .metric {
      padding: 0.95rem;
      border-radius: var(--radius-md);
      background: linear-gradient(180deg, #fff, #f7faff);
      border: 1px solid var(--line);
    }

    .metric strong {
      display: block;
      font-size: 1.3rem;
      letter-spacing: -0.03em;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .hero-card {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
      align-content: start;
      background:
        radial-gradient(circle at top right, rgba(245, 185, 75, 0.2), transparent 22%),
        linear-gradient(180deg, #ffffff, #f9fbff);
    }

    .deal-flag {
      width: fit-content;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: rgba(18, 104, 74, 0.1);
      color: var(--success);
      font-weight: 700;
      font-size: 0.85rem;
    }

    .deal-image {
      border-radius: 24px;
      overflow: hidden;
      aspect-ratio: 4 / 3;
      background: linear-gradient(135deg, #dfe8ff, #fff4d8);
      display: grid;
      place-items: center;
    }

    .deal-image svg {
      width: 74%;
      height: auto;
    }

    .deal-details {
      display: grid;
      gap: 0.5rem;
    }

    .deal-details p {
      color: var(--muted);
    }

    .status {
      min-height: 1.5rem;
      font-size: 0.95rem;
      color: var(--success);
      font-weight: 600;
    }

    .section {
      margin-top: 1.5rem;
    }

    .section-card {
      padding: clamp(1.2rem, 2.2vw, 1.6rem);
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-heading p {
      color: var(--muted);
      max-width: 54ch;
    }

    .grid {
      display: grid;
      gap: 1rem;
    }

    .featured-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .deal-grid {
      grid-template-columns: 1.05fr 0.95fr;
      align-items: stretch;
    }

    .editorial-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .product-card,
    .story-card,
    .deal-card {
      border-radius: var(--radius-lg);
      border: 1px solid var(--line);
      background: linear-gradient(180deg, #fff, #fbfcff);
      overflow: hidden;
      min-height: 100%;
    }

    .product-card {
      display: flex;
      flex-direction: column;
    }

    .product-card figure,
    .story-card figure {
      margin: 0;
    }

    .product-media {
      aspect-ratio: 4 / 3;
      background:
        linear-gradient(145deg, rgba(35, 71, 217, 0.08), rgba(245, 185, 75, 0.16)),
        linear-gradient(180deg, #edf2ff, #ffffff);
      display: grid;
      place-items: center;
      position: relative;
    }

    .product-media svg {
      width: 78%;
      height: auto;
    }

    .product-tag {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.35rem 0.7rem;
      border-radius: 999px;
      background: rgba(255,255,255,0.92);
      color: var(--brand-dark);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.02em;
      text-transform: uppercase;
      box-shadow: 0 8px 20px rgba(28, 40, 72, 0.08);
    }

    .product-body,
    .story-body,
    .deal-inner {
      padding: 1rem 1rem 1.1rem;
    }

    .product-body {
      display: grid;
      gap: 0.8rem;
      flex: 1;
    }

    .product-heading {
      display: grid;
      gap: 0.25rem;
    }

    .card-link {
      text-decoration: none;
      display: inline-block;
      width: fit-content;
      border-radius: 0.45rem;
    }

    .product-name {
      font-size: 1.08rem;
      line-height: 1.2;
    }

    .product-name a {
      text-decoration: none;
    }

    .product-meta {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .product-footer {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 0.75rem;
      margin-top: auto;
    }

    .price {
      display: grid;
      gap: 0.12rem;
    }

    .price strong {
      font-size: 1.15rem;
      letter-spacing: -0.03em;
    }

    .price span {
      color: var(--muted);
      font-size: 0.85rem;
    }

    .icon-button {
      width: 2.75rem;
      height: 2.75rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface);
      display: inline-grid;
      place-items: center;
      cursor: pointer;
      color: var(--brand-dark);
    }

    .deal-card {
      display: grid;
      grid-template-columns: 1fr 1fr;
    }

    .deal-card .deal-inner {
      display: grid;
      gap: 0.75rem;
      align-content: center;
    }

    .deal-card .badge {
      width: fit-content;
      padding: 0.35rem 0.7rem;
      border-radius: 999px;
      background: rgba(245, 185, 75, 0.18);
      color: #8a5a00;
      font-weight: 700;
      font-size: 0.8rem;
    }

    .deal-card ul {
      margin: 0;
      padding-left: 1.15rem;
      color: var(--muted);
      display: grid;
      gap: 0.45rem;
    }

    .deal-visual {
      background: linear-gradient(180deg, #f6f9ff, #ecf2ff);
      display: grid;
      place-items: center;
      min-height: 100%;
    }

    .deal-visual svg {
      width: 70%;
      height: auto;
    }

    .story-card {
      display: grid;
      gap: 0;
    }

    .story-image {
      aspect-ratio: 16 / 10;
      background: linear-gradient(145deg, rgba(35, 71, 217, 0.12), rgba(245, 185, 75, 0.14));
      display: grid;
      place-items: center;
    }

    .story-image svg {
      width: 74%;
      height: auto;
    }

    .story-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .story-body {
      display: grid;
      gap: 0.7rem;
    }

    .story-body h3 {
      font-size: 1.1rem;
    }

    .story-body p {
      color: var(--muted);
    }

    footer {
      padding: 1.5rem 0 2.5rem;
      color: var(--muted);
    }

    footer .footer-shell {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--line);
      flex-wrap: wrap;
    }

    nav[aria-label="Footer"] ul {
      display: flex;
      gap: 0.9rem;
      padding: 0;
      margin: 0;
      list-style: none;
      flex-wrap: wrap;
    }

    nav[aria-label="Footer"] a {
      color: inherit;
      padding: 0;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    :focus-visible {
      outline: 3px solid rgba(35, 71, 217, 0.6);
      outline-offset: 2px;
    }

    @media (max-width: 980px) {
      .hero,
      .deal-grid,
      .deal-card {
        grid-template-columns: 1fr;
      }

      .featured-grid,
      .editorial-grid,
      .hero-metrics {
        grid-template-columns: 1fr 1fr;
      }

      .hero-copy h1 {
        max-width: 14ch;
      }
    }

    @media (max-width: 640px) {
      .shell {
        width: min(100% - 1rem, var(--max));
      }

      .topbar {
        border-radius: 28px;
        padding: 1rem;
        align-items: flex-start;
      }

      .topbar,
      .section-heading {
        flex-direction: column;
        align-items: flex-start;
      }

      .hero-metrics,
      .featured-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .product-footer {
        align-items: center;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (forced-colors: active) {
      :focus-visible,
      .skip-link:focus {
        outline-color: Highlight;
      }

      .hero-copy,
      .hero-card,
      .section-card,
      .product-card,
      .story-card,
      .deal-card,
      .topbar,
      .button,
      .button-secondary,
      .icon-button {
        forced-color-adjust: auto;
        border-color: CanvasText;
        box-shadow: none;
      }

      .button {
        background: ButtonFace;
        color: ButtonText;
      }

      .button-secondary,
      .icon-button {
        background: Canvas;
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
