<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Luma Market — Fresh finds, daily deals, and stories</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --surface: #ffffff;
      --surface-alt: #eef3ff;
      --text: #172033;
      --muted: #5d687f;
      --line: #d8e0ef;
      --brand: #2347d9;
      --brand-dark: #1937b0;
      --accent: #f5b94b;
      --success: #12684a;
      --shadow: 0 18px 40px rgba(28, 40, 72, 0.08);
      --radius-xl: 28px;
      --radius-lg: 22px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --max: 1180px;
    }

    * { box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(35, 71, 217, 0.09), transparent 30%),
        radial-gradient(circle at top right, rgba(245, 185, 75, 0.11), transparent 26%),
        var(--bg);
      color: var(--text);
      line-height: 1.5;
      text-rendering: optimizeLegibility;
    }

    img {
      display: block;
      max-width: 100%;
    }

    a {
      color: inherit;
      text-decoration-thickness: 0.08em;
      text-underline-offset: 0.18em;
    }

    button,
    input {
      font: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1000;
      padding: 0.85rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      transform: translateY(-180%);
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--brand);
      outline-offset: 2px;
    }

    .shell {
      width: min(100% - 2rem, var(--max));
      margin: 0 auto;
    }

    header {
      padding: 1.1rem 0 0;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.15rem;
      background: rgba(255, 255, 255, 0.72);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(216, 224, 239, 0.8);
      border-radius: 999px;
      box-shadow: 0 12px 32px rgba(28, 40, 72, 0.06);
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      text-decoration: none;
      white-space: nowrap;
    }

    .brand-mark {
      width: 2.4rem;
      height: 2.4rem;
      border-radius: 18px;
      background:
        linear-gradient(135deg, var(--brand), #7e8cff);
      display: grid;
      place-items: center;
      color: #fff;
      box-shadow: inset 0 1px 0 rgba(255,255,255,0.25);
      font-size: 1.05rem;
    }

    nav[aria-label="Primary"] ul {
      display: flex;
      gap: 1rem;
      padding: 0;
      margin: 0;
      list-style: none;
      flex-wrap: wrap;
      justify-content: center;
    }

    nav a {
      padding: 0.55rem 0.85rem;
      border-radius: 999px;
      text-decoration: none;
      color: var(--muted);
      font-weight: 600;
    }

    nav a:hover,
    nav a:focus-visible {
      color: var(--text);
      background: rgba(35, 71, 217, 0.08);
      outline: none;
    }

    main {
      padding: 2rem 0 3rem;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
      gap: 1.5rem;
      align-items: stretch;
    }

    .hero-copy,
    .hero-card,
    .section-card {
      background: var(--surface);
      border: 1px solid rgba(216, 224, 239, 0.95);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.5rem, 3vw, 3rem);
      display: grid;
      gap: 1.2rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      margin: 0;
      padding: 0.4rem 0.8rem;
      border-radius: 999px;
      background: var(--surface-alt);
      color: var(--brand-dark);
      font-weight: 700;
      letter-spacing: 0.02em;
      text-transform: uppercase;
      font-size: 0.78rem;
    }

    h1,
    h2,
    h3,
    p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2.3rem, 4vw, 4.4rem);
      line-height: 0.98;
      letter-spacing: -0.05em;
      max-width: 12ch;
    }

    .hero-copy p {
      max-width: 58ch;
      font-size: 1.05rem;
      color: var(--muted);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      margin-top: 0.2rem;
    }

    .button,
    .button-secondary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3rem;
      padding: 0.8rem 1.2rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
    }

    .button {
      background: var(--brand);
      color: #fff;
      box-shadow: 0 16px 32px rgba(35, 71, 217, 0.22);
    }

    .button-secondary {
      background: transparent;
      color: var(--text);
      border-color: var(--line);
    }

    .button:hover,
    .button-secondary:hover,
    .card-link:hover,
    .button:focus-visible,
    .button-secondary:focus-visible,
    .card-link:focus-visible,
    .icon-button:focus-visible {
      transform: translateY(-1px);
      outline: 3px solid rgba(35, 71, 217, 0.2);
      outline-offset: 2px;
    }

    .hero-metrics {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.9rem;
      margin-top: 0.3rem;
    }

    .metric {
      padding: 0.95rem;
      border-radius: var(--radius-md);
      background: linear-gradient(180deg, #fff, #f7faff);
      border: 1px solid var(--line);
    }

    .metric strong {
      display: block;
      font-size: 1.3rem;
      letter-spacing: -0.03em;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .hero-card {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
      align-content: start;
      background:
        radial-gradient(circle at top right, rgba(245, 185, 75, 0.2), transparent 22%),
        linear-gradient(180deg, #ffffff, #f9fbff);
    }

    .deal-flag {
      width: fit-content;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: rgba(18, 104, 74, 0.1);
      color: var(--success);
      font-weight: 700;
      font-size: 0.85rem;
    }

    .deal-image {
      border-radius: 24px;
      overflow: hidden;
      aspect-ratio: 4 / 3;
      background: linear-gradient(135deg, #dfe8ff, #fff4d8);
      display: grid;
      place-items: center;
    }

    .deal-image svg {
      width: 74%;
      height: auto;
    }

    .deal-details {
      display: grid;
      gap: 0.5rem;
    }

    .deal-details p {
      color: var(--muted);
    }

    .status {
      min-height: 1.5rem;
      font-size: 0.95rem;
      color: var(--success);
      font-weight: 600;
    }

    .section {
      margin-top: 1.5rem;
    }

    .section-card {
      padding: clamp(1.2rem, 2.2vw, 1.6rem);
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-heading p {
      color: var(--muted);
      max-width: 54ch;
    }

    .grid {
      display: grid;
      gap: 1rem;
    }

    .featured-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .deal-grid {
      grid-template-columns: 1.05fr 0.95fr;
      align-items: stretch;
    }

    .editorial-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .product-card,
    .story-card,
    .deal-card {
      border-radius: var(--radius-lg);
      border: 1px solid var(--line);
      background: linear-gradient(180deg, #fff, #fbfcff);
      overflow: hidden;
      min-height: 100%;
    }

    .product-card {
      display: flex;
      flex-direction: column;
    }

    .product-card figure,
    .story-card figure {
      margin: 0;
    }

    .product-media {
      aspect-ratio: 4 / 3;
      background:
        linear-gradient(145deg, rgba(35, 71, 217, 0.08), rgba(245, 185, 75, 0.16)),
        linear-gradient(180deg, #edf2ff, #ffffff);
      display: grid;
      place-items: center;
      position: relative;
    }

    .product-media svg {
      width: 78%;
      height: auto;
    }

    .product-tag {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.35rem 0.7rem;
      border-radius: 999px;
      background: rgba(255,255,255,0.92);
      color: var(--brand-dark);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.02em;
      text-transform: uppercase;
      box-shadow: 0 8px 20px rgba(28, 40, 72, 0.08);
    }

    .product-body,
    .story-body,
    .deal-inner {
      padding: 1rem 1rem 1.1rem;
    }

    .product-body {
      display: grid;
      gap: 0.8rem;
      flex: 1;
    }

    .product-heading {
      display: grid;
      gap: 0.25rem;
    }

    .card-link {
      text-decoration: none;
      display: inline-block;
      width: fit-content;
      border-radius: 0.45rem;
    }

    .product-name {
      font-size: 1.08rem;
      line-height: 1.2;
    }

    .product-name a {
      text-decoration: none;
    }

    .product-meta {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .product-footer {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 0.75rem;
      margin-top: auto;
    }

    .price {
