      height: 2.75rem;
      padding: 0 0.9rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface);
      display: inline-grid;
      place-items: center;
      cursor: pointer;
      color: var(--brand-dark);
    }

    .deal-card {
