      display: grid;
      gap: 0.45rem;
    }

    .deal-visual {
      background: linear-gradient(180deg, #f6f9ff, #ecf2ff);
      display: grid;
      place-items: center;
      min-height: 100%;
    }

    .deal-visual svg {
      width: 70%;
      height: auto;
    }

    .story-card {
      display: grid;
      gap: 0;
    }

    .story-image {
      aspect-ratio: 16 / 10;
      background: linear-gradient(145deg, rgba(35, 71, 217, 0.12), rgba(245, 185, 75, 0.14));
      display: grid;
      place-items: center;
    }

    .story-image svg {
      width: 74%;
      height: auto;
    }

    .story-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .story-body {
      display: grid;
      gap: 0.7rem;
    }

    .story-body h3 {
      font-size: 1.1rem;
    }

    .story-body p {
      color: var(--muted);
    }

    footer {
      padding: 1.5rem 0 2.5rem;
      color: var(--muted);
    }

    footer .footer-shell {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
